248		}
249	
250		// 核对（10-05）：最近证书是较新的合格 C-NEW，器具可以使用；历史按
251		// 校准日期由近到远，较早的 C-OLD 仍如实显示超差。
252		clock.t = mustDate(t, "2026-10-05")
253		r, err := l.Review("M-1")
254		if err != nil {
255			t.Fatalf("review: %v", err)
256		}
257		if !r.CanUse || len(r.Reasons) != 0 {
258			t.Fatalf("最近证书合格未到期时应可以使用，得到 reasons=%v", r.Reasons)
259		}
260		if r.Latest == nil || r.Latest.Number != "C-NEW" || !r.Latest.Pass || r.Latest.Expired {
261			t.Fatalf("最近证书应是较新的合格未到期证书 C-NEW：%+v", r.Latest)
262		}
263		if len(r.History) != 2 ||
264			r.History[0].Number != "C-NEW" || !r.History[0].Pass ||
265			r.History[1].Number != "C-OLD" || r.History[1].Pass {
266			t.Fatalf("历史应由近到远为合格 C-NEW、超差 C-OLD：%+v", r.History)
267		}
268		if len(r.Plans) != 1 || r.Plans[0].Status != PlanStatusDone ||
269			r.Plans[0].CertificateNumber != "C-OLD" {
270			t.Fatalf("计划应保留与较早超差证书的关联：%+v", r.Plans)
271		}
272		assertCertAndInstrumentUnchanged(t, l, map[string]Certificate{
273			"C-NEW": {CalDate: "2026-09-20", Expiry: "2027-09-20", Error: 0.1},
274			"C-OLD": {CalDate: "2026-09-10", Expiry: "2027-09-10", Error: 5},
275		})
276	
277		// 使用申请以较新证书为准，获准并留痕。
278		d, err := l.RequestUse("M-1")
279		if err != nil {
280			t.Fatalf("request use: %v", err)
281		}
282		if !d.Allowed || len(d.Reasons) != 0 {
283			t.Fatalf("应获准使用，得到 allowed=%v reasons=%v", d.Allowed, d.Reasons)
284		}
285		r2, _ := l.Review("M-1")
286		if len(r2.Rejections) != 0 {
287			t.Fatalf("获准使用不应产生拒绝记录，得到 %d 条", len(r2.Rejections))
288		}
289		recs := l.UsageRecords()
290		if len(recs) != 1 || !recs[0].Allowed {
291			t.Fatalf("应留下 1 条获准记录，得到 %+v", recs)
292		}
293	}
294	
295	// TestCompletePlanCertDateBoundaryAroundCreationDay 日期边界围绕计划最初建立的
296	// 本机日期：校准日期等于建立日期可完成，早一天则明确拒绝；拒绝后计划继续未完成
297	// 并留在待办，不写入完成时间或关联证书，随后仍可用边界当天的证书正常完成。
298	func TestCompletePlanCertDateBoundaryAroundCreationDay(t *testing.T) {
299		// 计划建立于 2026-09-10；完成动作发生在更晚的 09-15，比较只以保存的
300		// 建立日期为准，而不是操作当天。
301		clock := &fakeClock{t: mustDate(t, "2026-09-10")}
302		l := newTestLedger(t, clock)
303		mustRegister(t, l, "M-1", "万用表", 0.5)
304		mustPlan(t, l, PlanInput{
305			Number: "PL-1", InstrumentID: "M-1", Date: "2026-09-20", Note: "周期校准",
306		})
307	
308		clock.t = mustDate(t, "2026-09-15")
309		mustAddCert(t, l, CertificateInput{
310			InstrumentID: "M-1", Number: "C-TOO-EARLY", CalDate: "2026-09-09",
311			Expiry: "2027-09-09", Method: "m", Error: 0.1, Summary: "早一天",
312		})
313		_, _, err := l.CompletePlan("PL-1", "C-TOO-EARLY")
314		if !IsValidation(err) ||
315			!strings.Contains(err.Error(), "早于") || !strings.Contains(err.Error(), "建立日期") {
316			t.Fatalf("校准日期早于建立日期一天应明确拒绝并说明边界，得到 %v", err)
317		}
318		assertPlanStillOpen(t, l, "PL-1")
319		// 被拒绝的证书本身仍是一张正常历史证书，不被删除。
320		if l.findCertificate("C-TOO-EARLY") == nil {
321			t.Fatal("日期不符的拒绝不应删除证书")
322		}
323	
324		// 校准日期恰好等于建立日期：可以完成；完成时间取本次成功操作。
325		mustAddCert(t, l, CertificateInput{
326			InstrumentID: "M-1", Number: "C-ON-DAY", CalDate: "2026-09-10",
327			Expiry: "2027-09-10", Method: "m", Error: 0.1, Summary: "建立当天",
328		})
329		done, idem, err := l.CompletePlan("PL-1", "C-ON-DAY")
330		if err != nil || idem {
331			t.Fatalf("校准日期等于建立日期应可完成，err=%v idempotent=%v", err, idem)
332		}
333		if done.Status != PlanStatusDone || done.CertificateNumber != "C-ON-DAY" ||
334			!strings.HasPrefix(done.CompletedAt, "2026-09-15T") {
335			t.Fatalf("边界当天完成结果异常：%+v", done)
336		}
337		if items, _ := l.Todos(""); len(items) != 0 {
338			t.Fatalf("完成后待办应为空，得到 %+v", items)
339		}
340	
341		// 已完成后再用那张早一天的证书试图更换关联：仍拒绝，原完成信息不变。
342		_, _, err = l.CompletePlan("PL-1", "C-TOO-EARLY")
343		if !IsValidation(err) {
344			t.Fatalf("已完成计划换证书应拒绝，得到 %v", err)
345		}
346		p := l.findPlan("PL-1")
347		if p.Status != PlanStatusDone || p.CertificateNumber != "C-ON-DAY" ||
348			p.CompletedAt != done.CompletedAt {
349			t.Fatalf("拒绝换证书后原完成信息被改动：%+v", p)
350		}
351	}
