267		got := l.findCertificate("C-1")
268		if got.InstrumentID != "M-1" || got.Error != 0.1 {
269			t.Fatalf("冲突后已有数据被改动：%+v", got)
270		}
271	
272		// 证书编号在整个台账中唯一：M-2 不能再用 C-1。
273		if n := len(l.data.Certificates); n != 1 {
274			t.Fatalf("冲突提交不应产生记录，共 %d 张", n)
275		}
276	}
