467	// certArgs 构造一条录入证书的完整参数，便于按需替换个别字段。
468	func certArgs(path, number, calDate, method, summary string) []string {
469		return []string{"cert", "-f", path,
470			"--instrument", "M-1", "--number", number,
471			"--cal-date", calDate, "--expiry", "2027-09-01",
472			"--method", method, "--error", "0.1", "--summary", summary}
473	}
474	
475	// 证书字段的值即使看起来是全局参数（--json、-f…、--file=…），也必须按文字
476	// 保存：不改变目标台账、不开启 JSON 输出，并能在随后核对与重开后完整查到。
477	func TestCertFieldValuesResemblingGlobalFlags(t *testing.T) {
478		dir := chdirTemp(t)
479		target := filepath.Join(dir, "真台账.json")
480		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
481			t.Fatal(r.stderr)
482		}
483	
484		// 摘要为 --json 且没有另行开启 JSON：录入成功并保持普通文字输出。
485		r := runArgs(t, certArgs(target, "C-1", "2026-09-01", "比较法", "--json")...)
486		if r.code != 0 {
487			t.Fatalf("摘要为 --json 应录入成功，code=%d stderr=%s", r.code, r.stderr)
488		}
489		if strings.HasPrefix(strings.TrimSpace(r.stdout), "{") {
490			t.Fatalf("未开启 --json 不应输出 JSON：%q", r.stdout)
491		}
492	
493		// 校准方法为 -f备用.json：仍写入真正指定的台账，不创建“备用.json”。
494		r = runArgs(t, certArgs(target, "C-2", "2026-09-02", "-f备用.json", "例行")...)
495		if r.code != 0 {
496			t.Fatalf("方法为 -f备用.json 应录入成功，code=%d stderr=%s", r.code, r.stderr)
497		}
498		// 校准方法为 --file=另一本.json：不参与台账选择，也不创建该文件。
499		r = runArgs(t, certArgs(target, "C-3", "2026-09-03", "--file=另一本.json", "等号形式")...)
500		if r.code != 0 {
501			t.Fatalf("方法为 --file=… 应录入成功，code=%d stderr=%s", r.code, r.stderr)
502		}
503		for _, stray := range []string{"备用.json", "另一本.json", "ledger.json"} {
504			if fileExists(t, filepath.Join(dir, stray)) {
505				t.Fatalf("字段值被误当成全局参数，产生了 %s", stray)
506			}
507		}
508	
509		// 按器具核对的 JSON 结果中完整查到这些文字；退出后重开同一台账保持一致。
510		want := map[string][2]string{
511			"C-1": {"比较法", "--json"},
512			"C-2": {"-f备用.json", "例行"},
513			"C-3": {"--file=另一本.json", "等号形式"},
514		}
515		for i := 0; i < 2; i++ {
516			rv := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
517			if rv.code != 0 {
518				t.Fatalf("review 失败 code=%d stderr=%s", rv.code, rv.stderr)
519			}
520			var view struct {
521				History []struct {
522					Number  string `json:"number"`
523					Method  string `json:"method"`
524					Summary string `json:"summary"`
525				} `json:"history"`
526			}
527			if err := json.Unmarshal([]byte(rv.stdout), &view); err != nil {
528				t.Fatalf("review JSON 解析失败: %v\n%s", err, rv.stdout)
529			}
530			got := map[string][2]string{}
531			for _, h := range view.History {
532				got[h.Number] = [2]string{h.Method, h.Summary}
533			}
534			for number, ms := range want {
535				if got[number] != ms {
536					t.Fatalf("第 %d 次核对 %s 内容不符：got=%v want=%v", i+1, number, got[number], ms)
537				}
538			}
539		}
540	}
541	
542	// 字段名与值分开传入、用等号连在一起传入，应得到相同的证书内容。
543	func TestCertSplitAndEqualsFormsMatch(t *testing.T) {
544		dir := chdirTemp(t)
545		target := filepath.Join(dir, "台账.json")
546		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
547			t.Fatal(r.stderr)
548		}
549		split := certArgs(target, "C-1", "2026-09-01", "--json", "--json")
550		// 同样的内容用等号连在一起传入（日期错开，避开同日限制）。
551		equals := []string{"cert", "-f", target,
552			"--instrument=M-1", "--number=C-2",
553			"--cal-date=2026-09-02", "--expiry=2027-09-02",
554			"--method=--json", "--error=0.1", "--summary=--json"}
555		if r := runArgs(t, split...); r.code != 0 {
556			t.Fatalf("分开传入失败 code=%d stderr=%s", r.code, r.stderr)
557		}
558		if r := runArgs(t, equals...); r.code != 0 {
559			t.Fatalf("等号传入失败 code=%d stderr=%s", r.code, r.stderr)
560		}
561		rv := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
562		var view struct {
563			History []struct {
564				Number  string `json:"number"`
565				Method  string `json:"method"`
566				Summary string `json:"summary"`
567			} `json:"history"`
568		}
569		if err := json.Unmarshal([]byte(rv.stdout), &view); err != nil {
570			t.Fatal(err)
571		}
572		got := map[string][2]string{}
573		for _, h := range view.History {
574			got[h.Number] = [2]string{h.Method, h.Summary}
575		}
576		if got["C-1"] != got["C-2"] || got["C-1"] != [2]string{"--json", "--json"} {
577			t.Fatalf("两种写法内容应一致且为 --json：%v", got)
578		}
579	}
580	
581	// 需要值的证书参数放在命令末尾却没有值：明确报参数错误并退出 2，
582	// 不创建证书、不改动台账。
583	func TestCertTrailingFlagMissingValue(t *testing.T) {
584		dir := chdirTemp(t)
585		target := filepath.Join(dir, "台账.json")
586		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
587			t.Fatal(r.stderr)
588		}
589		args := certArgs(target, "C-9", "2026-09-01", "比较法", "例行")
590		// 去掉 --summary 的值，让标志悬在末尾。
591		args = args[:len(args)-1]
592		r := runArgs(t, args...)
593		if r.code != 2 {
594			t.Fatalf("末尾缺值应退出 2，得到 %d", r.code)
595		}
596		rv := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
597		if !strings.Contains(rv.stdout, `"history": []`) &&
598			!strings.Contains(rv.stdout, `"history": null`) {
599			t.Fatalf("缺值录入不应产生证书：%s", rv.stdout)
600		}
601	}
602	
603	// 同号且业务内容一致（即使内容像全局参数）返回原证书、不增加历史；
604	// 同号内容不同仍拒绝覆盖。
605	func TestCertDuplicateJudgmentUnchanged(t *testing.T) {
606		dir := chdirTemp(t)
607		target := filepath.Join(dir, "台账.json")
608		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
609			t.Fatal(r.stderr)
610		}
611		first := certArgs(target, "C-1", "2026-09-01", "-f备用.json", "--json")
612		if r := runArgs(t, first...); r.code != 0 {
613			t.Fatal(r.stderr)
614		}
615		r := runArgs(t, first...)
616		if r.code != 0 || !strings.Contains(r.stdout, "未增加历史") {
617			t.Fatalf("同号同内容应幂等返回原证书，code=%d stdout=%q", r.code, r.stdout)
618		}
619		conflict := certArgs(target, "C-1", "2026-09-01", "-f备用.json", "别的摘要")
620		if r := runArgs(t, conflict...); r.code != 1 {
621			t.Fatalf("同号内容不同应冲突退出 1，得到 %d", r.code)
622		}
623	}
