1	package calibrate
2	
3	import (
4		"path/filepath"
5		"testing"
6	)
7	
8	// TestReturnedReasonsCannotRewriteHistory 验证调用方整理各公开入口返回的
9	// 原因不会改写台账内已冻结的历史，也不会随正常写盘进入文件。
10	func TestReturnedReasonsCannotRewriteHistory(t *testing.T) {
11		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
12		path := filepath.Join(t.TempDir(), "ledger.json")
13		l, err := openAt(path, clock.now)
14		if err != nil {
15			t.Fatalf("open: %v", err)
16		}
17		mustRegister(t, l, "M-1", "万用表", 0.5)
18	
19		// 待校准且没有证书：申请被拒绝，原记录同时保留两条原因。
20		d, err := l.RequestUse("M-1")
21		if err != nil || d.Allowed {
22			t.Fatalf("待校准无证书应拒绝，err=%v allowed=%v", err, d.Allowed)
23		}
24		want := append([]string(nil), d.Reasons...)
25		if len(want) != 2 {
26			t.Fatalf("应同时保留状态与无证书两个原因，得到 %v", want)
27		}
28	
29		// 调用方在返回结果中替换、删减、补充原因，只影响自己那份展示数据。
30		d.Reasons[0] = "显示用短句"
31		d.Reasons = append(d.Reasons[:1], "调用方自己补的原因")
32	
33		recs := l.UsageRecords()
34		if len(recs) != 1 || !sameReasons(recs[0].Reasons, want) {
35			t.Fatalf("全部使用记录被申请返回值改写：保存=%v 读到=%v", want, recs)
36		}
37		r, _ := l.Review("M-1")
38		if len(r.Rejections) != 1 || !sameReasons(r.Rejections[0].Reasons, want) {
39			t.Fatalf("核对视图历史拒绝被申请返回值改写：保存=%v 读到=%v",
40				want, r.Rejections)
41		}
42	
43		// 整理核对结果中的历史拒绝，也不能影响全部使用记录或再次核对。
44		r.Rejections[0].Reasons[0] = "另一条显示短句"
45		r.Rejections[0].Reasons = r.Rejections[0].Reasons[:1]
46		recs = l.UsageRecords()
47		if !sameReasons(recs[0].Reasons, want) {
48			t.Fatalf("整理核对结果改写了全部使用记录：保存=%v 读到=%v",
49				want, recs[0].Reasons)
50		}
51		r2, _ := l.Review("M-1")
52		if !sameReasons(r2.Rejections[0].Reasons, want) {
53			t.Fatalf("整理核对结果改写了再次核对的历史：保存=%v 读到=%v",
54				want, r2.Rejections[0].Reasons)
55		}
56	
57		// 整理全部使用记录，不能影响已经取得或之后取得的核对结果。
58		recs[0].Reasons[0] = "记录清单里的短句"
59		if !sameReasons(r2.Rejections[0].Reasons, want) {
60			t.Fatal("整理全部使用记录影响了此前已取得的核对结果")
61		}
62		r3, _ := l.Review("M-1")
63		if !sameReasons(r3.Rejections[0].Reasons, want) {
64			t.Fatalf("整理全部使用记录改写了之后核对的历史：%v",
65				r3.Rejections[0].Reasons)
66		}
67	
68		// 补录合格证书并切换为在用：当前核对允许使用，但此前拒绝保持原原因。
69		_ = l.SetStatus("M-1", StatusInUse)
70		mustAddCert(t, l, CertificateInput{
71			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
72			Expiry: "2027-09-01", Method: "m", Error: 0, Summary: "s",
73		})
74		r, _ = l.Review("M-1")
75		if !r.CanUse {
76			t.Fatalf("补录合格证书并在用后当前应允许使用，得到 %v", r.Reasons)
77		}
78		if len(r.Rejections) != 1 || !sameReasons(r.Rejections[0].Reasons, want) {
79			t.Fatalf("状态变化后历史拒绝原因被改写：保存=%v 读到=%v",
80				want, r.Rejections)
81		}
82	
83		// 正常操作触发台账写盘后，从同一文件读出的历史仍保持原样。
84		reopened, err := openAt(path, clock.now)
85		if err != nil {
86			t.Fatalf("reopen: %v", err)
87		}
88		recs = reopened.UsageRecords()
89		if len(recs) != 1 || recs[0].Allowed || !sameReasons(recs[0].Reasons, want) {
90			t.Fatalf("写盘后历史拒绝被污染：%+v", recs)
91		}
