package calibrate

import (
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// 本文件为“申请使用器具”补充可重复执行的回归保障，重点保护：
//
//	“最近证书到期后，不能借用较早证书继续获准使用”。
//
// 场景：器具保持在用，两张证书都按允许误差判为合格；校准日期较新的证书
// （C-NEW）先到期，较早证书（C-OLD）的有效期仍覆盖“新证截止日”这一天。
// 即便历史中还有一张合格且未到期的旧证书，最近证书（按校准日期确定，与录入
// 先后、编号大小、有效期长短都无关）到期也必须拒绝使用，绝不回退到旧证书。
//
// 为保证日历日期变化后仍可重复执行，所有日期都从一个固定锚点（测试开始
// 取一次，并非写死的未来日期）派生：
//
//	newCal  = 锚点前 40 天   （较新校准日期，在旧证之后、新证之前）
//	oldCal  = 锚点前 200 天  （较早校准日期）
//	newExp  = 锚点前 1 天    （较新证书截止日；锚点当天即到期）
//	oldExp  = 锚点后 400 天  （较早证书有效期很长，仍覆盖申请当天）
//
// 关键点：C-OLD 校准更早但有效期更长（录入也可能更晚），这些都不能让它成为
// 最近证书或顶替到期的 C-NEW 决定使用资格。

// dynDates 是从运行当天派生的两张证书的日期。
type dynDates struct {
	anchor    time.Time // 测试开始取一次的锚点（较新证书截止日的次日）
	before    time.Time // 新证截止日前一天（此时两张证书都未到期）
	deadline  time.Time // 新证截止日当天（当天即到期）
	oldCal    string
	newCal    string
	oldExp    string
	newExp    string
	newExpRaw time.Time
}

func dynTwoCertDates(t *testing.T) dynDates {
	t.Helper()
	// 锚点不写死任何日期：取运行当天，保证截止日前/当天的区别在任何日历下
	// 都能被覆盖，不依赖某个固定日期恰好仍在未来。
	anchor := time.Now()
	d := dynDates{
		anchor:    anchor,
		before:    anchor.AddDate(0, 0, -2),
		before2:   anchor.AddDate(0, 0, -2),
		deadline:  anchor.AddDate(0, 0, -1),
		newExpRaw: anchor.AddDate(0, 0, -1),
	}
	d.newCal = anchor.AddDate(0, 0, -40).Format(DateLayout)
	d.oldCal = anchor.AddDate(0, 0, -200).Format(DateLayout)
	d.newExp = anchor.AddDate(0, 0, -1).Format(DateLayout)
	d.oldExp = anchor.AddDate(0, 0, 400).+400).Format(DateLayout)
	return d
}

